      stockLeft: product.stockLeft,
      units: product.units,
      code: product.code,
      image: product.imageFile || product.images?.[0] || "",
    };

    if (index === -1) {
      category.products.push(item);
    } else {       
      category.products[index] = item;
    }
  }
  localStorage.setItem("allCategories", JSON.stringify(stored));
};

